+
+    fn start_visual_selection(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        let pane = self.active_text_pane();
+        let position = self.current_text_position(pane, right_content, right_cursor_column);
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: position,
+            cursor: position,
+        });
+        self.mode = UiMode::Command;
+    }
+
+    fn handle_visual_key(&mut self, key: UiKey, right_content: &str) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.visual_selection = None;
+            }
+            UiKey::Char('v') => {
+                self.set_visual_selection_kind(VisualSelectionKind::Character);
+            }
+            UiKey::Char('V') => {
+                self.set_visual_selection_kind(VisualSelectionKind::Line);
+            }
+            UiKey::Char('\u{16}') => {
+                self.set_visual_selection_kind(VisualSelectionKind::Block);
+            }
+            UiKey::Char('y') => {
+                self.copy_visual_selection(right_content, false);
+            }
+            UiKey::Char('Y') => {
+                self.copy_visual_selection(right_content, true);
+            }
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_cursor(0, -1, right_content);
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_cursor(1, 0, right_content);
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_cursor(-1, 0, right_content);
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_cursor(0, 1, right_content);
+            }
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn set_visual_selection_kind(&mut self, kind: VisualSelectionKind) {
+        if let Some(selection) = &mut self.visual_selection {
+            selection.kind = kind;
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize, right_content: &str) {
+        let Some(pane) = self.visual_selection.as_ref().map(|selection| selection.pane) else {
+            return;
+        };
+        let lines = self.selection_text_lines(pane, right_content);
+        let Some(selection) = &mut self.visual_selection else {
+            return;
+        };
+        let max_row = lines.len().saturating_sub(1);
+        let next_row = (selection.cursor.row as isize + row_delta).clamp(0, max_row as isize);
+        let next_row = next_row as usize;
+        let max_column = lines
+            .get(next_row)
+            .map(|line| line_char_count(line).saturating_sub(1))
+            .unwrap_or(0);
+        let next_column =
+            (selection.cursor.column as isize + column_delta).clamp(0, max_column as isize);
+        selection.cursor = TextPosition {
+            row: next_row,
+            column: next_column as usize,
+        };
+    }
+
+    fn copy_visual_selection(&mut self, right_content: &str, force_line: bool) {
+        let Some(text) = self.visual_selected_text(right_content, force_line) else {
+            return;
+        };
+        self.visual_selection = None;
+        self.store_clipboard(text);
+    }
+
+    fn copy_current_line(&mut self, right_content: &str, right_cursor_column: Option<usize>) {
+        let pane = self.active_text_pane();
+        let lines = self.selection_text_lines(pane, right_content);
+        let position = self.current_text_position(pane, right_content, right_cursor_column);
+        self.store_clipboard(lines.get(position.row).cloned().unwrap_or_default());
+    }
+
+    fn store_clipboard(&mut self, text: String) {
+        let copied_chars = text.chars().count();
+        self.clipboard_text = Some(text);
+        self.pending_clipboard.set(true);
+        self.show_status_notice(
+            format!("copied {copied_chars} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn visual_selected_text(&self, right_content: &str, force_line: bool) -> Option<String> {
+        let selection = self.visual_selection.as_ref()?;
+        let lines = self.selection_text_lines(selection.pane, right_content);
+        Some(selected_text_from_lines(&lines, selection, force_line))
+    }
+
+    fn visual_selection_range(
+        &self,
+        pane: PaneFocus,
+        row: usize,
+        line: &str,
+    ) -> Option<(usize, usize)> {
+        let selection = self.visual_selection.as_ref()?;
+        if selection.pane != pane {
+            return None;
+        }
+
+        let (start, end) = selection.ordered_positions();
+        if row < start.row || row > end.row {
+            return None;
+        }
+
+        let line_len = line_char_count(line);
+        match selection.kind {
+            VisualSelectionKind::Line => Some((0, line_len)),
+            VisualSelectionKind::Block => {
+                let (start_column, end_column) = ordered_columns(selection);
+                Some((start_column.min(line_len), end_column.saturating_add(1).min(line_len)))
+            }
+            VisualSelectionKind::Character if start.row == end.row => Some((
+                start.column.min(line_len),
+                end.column.saturating_add(1).min(line_len),
+            )),
+            VisualSelectionKind::Character if row == start.row => {
+                Some((start.column.min(line_len), line_len))
+            }
+            VisualSelectionKind::Character if row == end.row => {
+                Some((0, end.column.saturating_add(1).min(line_len)))
+            }
+            VisualSelectionKind::Character => Some((0, line_len)),
+        }
+    }
+
+    fn visual_cursor_position(&self, right_content: &str) -> Option<(u16, u16)> {
+        let selection = self.visual_selection.as_ref()?;
+        match selection.pane {
+            PaneFocus::Left => {
+                let lines = self.left_text_lines();
+                let position = clamp_text_position(selection.cursor, &lines);
+                Some((
+                    position.row.saturating_add(2).min(usize::from(u16::MAX)) as u16,
+                    position.column.saturating_add(2).min(usize::from(u16::MAX)) as u16,
+                ))
+            }
+            PaneFocus::Right => {
+                let lines = text_lines(right_content);
+                let position = clamp_text_position(selection.cursor, &lines);
+                let layout = self.layout();
+                Some((
+                    position.row.saturating_add(2).min(usize::from(u16::MAX)) as u16,
+                    usize::from(layout.left_width)
+                        .saturating_add(position.column)
+                        .saturating_add(2)
+                        .min(usize::from(u16::MAX)) as u16,
+                ))
+            }
+        }
+    }
+
+    fn selection_text_lines(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self.left_text_lines(),
+            PaneFocus::Right => text_lines(&self.visible_right_content(right_content)),
+        }
+    }
+
+    fn active_text_pane(&self) -> PaneFocus {
+        if self.focus == PaneFocus::Left && !self.left_visible {
+            PaneFocus::Right
+        } else {
+            self.focus
+        }
+    }
+
+    fn current_text_position(
+        &self,
+        pane: PaneFocus,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> TextPosition {
+        let lines = self.selection_text_lines(pane, right_content);
+        let position = match pane {
+            PaneFocus::Left => TextPosition {
+                row: self.control_display_row(),
+                column: 0,
+            },
+            PaneFocus::Right => TextPosition {
+                row: lines.len().saturating_sub(1),
+                column: right_cursor_column.unwrap_or_default(),
+            },
+        };
+        clamp_text_position(position, &lines)
+    }
@@
     fn control_cursor_row(&self) -> u16 {
         (self.control_selected + 2).min(usize::from(u16::MAX)) as u16
     }
