+impl VisualSelection {
+    fn ordered_positions(&self) -> (TextPosition, TextPosition) {
+        if self.anchor.row < self.cursor.row
+            || (self.anchor.row == self.cursor.row && self.anchor.column <= self.cursor.column)
+        {
+            (self.anchor, self.cursor)
+        } else {
+            (self.cursor, self.anchor)
+        }
+    }
+}
+
+impl VisualSelectionKind {
+    fn as_str(&self) -> &'static str {
+        match self {
+            Self::Character => "char",
+            Self::Line => "line",
+            Self::Block => "block",
+        }
+    }
+}
