+fn text_lines(content: &str) -> Vec<String> {
+    if content.is_empty() {
+        vec![String::new()]
+    } else {
+        content.split('\n').map(str::to_string).collect()
+    }
+}
+
+fn clamp_text_position(position: TextPosition, lines: &[String]) -> TextPosition {
+    let row = position.row.min(lines.len().saturating_sub(1));
+    let max_column = lines
+        .get(row)
+        .map(|line| line_char_count(line).saturating_sub(1))
+        .unwrap_or(0);
+    TextPosition {
+        row,
+        column: position.column.min(max_column),
+    }
+}
+
+fn selected_text_from_lines(
+    lines: &[String],
+    selection: &VisualSelection,
+    force_line: bool,
+) -> String {
+    if lines.is_empty() {
+        return String::new();
+    }
+
+    let max_row = lines.len().saturating_sub(1);
+    let (start, end) = selection.ordered_positions();
+    let start_row = start.row.min(max_row);
+    let end_row = end.row.min(max_row);
+
+    if force_line || selection.kind == VisualSelectionKind::Line {
+        return (start_row..=end_row)
+            .map(|row| lines[row].clone())
+            .collect::<Vec<_>>()
+            .join("\n");
+    }
+
+    match selection.kind {
+        VisualSelectionKind::Block => {
+            let (start_column, end_column) = ordered_columns(selection);
+            (start_row..=end_row)
+                .map(|row| {
+                    line_slice_chars(&lines[row], start_column, end_column.saturating_add(1))
+                })
+                .collect::<Vec<_>>()
+                .join("\n")
+        }
+        VisualSelectionKind::Character => (start_row..=end_row)
+            .map(|row| {
+                let line = &lines[row];
+                let line_len = line_char_count(line);
+                let (start_column, end_column) = if start_row == end_row {
+                    (
+                        start.column.min(line_len),
+                        end.column.saturating_add(1).min(line_len),
+                    )
+                } else if row == start_row {
+                    (start.column.min(line_len), line_len)
+                } else if row == end_row {
+                    (0, end.column.saturating_add(1).min(line_len))
+                } else {
+                    (0, line_len)
+                };
+                line_slice_chars(line, start_column, end_column)
+            })
+            .collect::<Vec<_>>()
+            .join("\n"),
+        VisualSelectionKind::Line => unreachable!("line selection returned earlier"),
+    }
+}
+
+fn ordered_columns(selection: &VisualSelection) -> (usize, usize) {
+    if selection.anchor.column <= selection.cursor.column {
+        (selection.anchor.column, selection.cursor.column)
+    } else {
+        (selection.cursor.column, selection.anchor.column)
+    }
+}
+
+fn spans_with_selection(line: &str, range: Option<(usize, usize)>) -> Vec<Span<'static>> {
+    let Some((start, end)) = range else {
+        return vec![Span::raw(line.to_string())];
+    };
+    let line_len = line_char_count(line);
+    let start = start.min(line_len);
+    let end = end.min(line_len);
+    if start >= end {
+        return vec![Span::raw(line.to_string())];
+    }
+
+    let start_byte = byte_index_at_char(line, start);
+    let end_byte = byte_index_at_char(line, end);
+    let mut spans = Vec::new();
+    if start_byte > 0 {
+        spans.push(Span::raw(line[..start_byte].to_string()));
+    }
+    spans.push(Span::styled(
+        line[start_byte..end_byte].to_string(),
+        Style::default().add_modifier(Modifier::REVERSED),
+    ));
+    if end_byte < line.len() {
+        spans.push(Span::raw(line[end_byte..].to_string()));
+    }
+    spans
+}
+
+fn line_slice_chars(line: &str, start: usize, end: usize) -> String {
+    let line_len = line_char_count(line);
+    let start = start.min(line_len);
+    let end = end.min(line_len);
+    if start >= end {
+        return String::new();
+    }
+
+    let start_byte = byte_index_at_char(line, start);
+    let end_byte = byte_index_at_char(line, end);
+    line[start_byte..end_byte].to_string()
+}
+
+fn byte_index_at_char(line: &str, char_index: usize) -> usize {
+    line.char_indices()
+        .nth(char_index)
+        .map(|(index, _)| index)
+        .unwrap_or(line.len())
+}
+
+fn line_char_count(line: &str) -> usize {
+    line.chars().count()
+}
+
+fn osc52_clipboard_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut output = String::with_capacity(bytes.len().saturating_add(2) / 3 * 4);
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = chunk.get(1).copied().unwrap_or(0);
+        let third = chunk.get(2).copied().unwrap_or(0);
+
+        output.push(TABLE[(first >> 2) as usize] as char);
+        output.push(TABLE[(((first & 0b0000_0011) << 4) | (second >> 4)) as usize] as char);
+        if chunk.len() > 1 {
+            output.push(TABLE[(((second & 0b0000_1111) << 2) | (third >> 6)) as usize] as char);
+        } else {
+            output.push('=');
+        }
+        if chunk.len() > 2 {
+            output.push(TABLE[(third & 0b0011_1111) as usize] as char);
+        } else {
+            output.push('=');
+        }
+    }
+    output
+}
